-- patch_a2_vague_2026-11-25_REPETITION -- LECTURE SEULE, apres le geste.
select (select count(*) from public.app_classeur_realignement_journal where lot = 'a2_vague_2026-11-25') as journal_attendu_343,
       (select count(*) from public.app_affaire_repartition where ecrit_par like 'a2_vague_2026-11-25:%') as parts_du_lot_attendu_199_plus_1,
       (select count(*) from public.app_affaire_repartition_mise_de_cote where mise_de_cote_par = 'patch_a2_vague_2026-11-25') as mises_de_cote_attendu_143,
       (select coalesce(string_agg(c::text, ',' order by c), '') from (
    select distinct l.app_chaine_id c from public.app_affaire_ledger l
     where l.kind = 'vente' and coalesce(l.vente_reglee_app, '') <> '' and l.app_chaine_id is not null
       and not exists (select 1 from public.app_affaire_repartition r where r.app_chaine_id = l.app_chaine_id)) x) as ventes_reglees_sans_part_attendu_vide,
       (select count(*) from public.app_affaire_repartition r where not exists (select 1 from public.app_affaire_ledger l
         where l.app_chaine_id = r.app_chaine_id)) as parts_orphelines_attendu_0,
       (select md5(coalesce(string_agg(x, ';' order by c), '')) from (
     select app_chaine_id c, app_chaine_id || ':' || string_agg(app_affaire_id::text, ',' order by app_affaire_id) x
       from public.app_affaire_ledger where app_chaine_id in (21, 117, 118, 125, 126, 1059, 1060, 1103, 1160, 1161, 2166, 2167, 2210, 2211, 2357, 2358, 2633, 2634, 3676, 3677, 3699, 3701, 3719, 3720, 4196, 4267, 4269, 4271, 4272, 4277, 4278, 4290, 4370, 4371, 4372, 4388, 4480, 4481, 4484, 4500, 4501, 4508, 4509, 4533, 4534, 4560, 4561, 4621, 4622, 4649, 4650, 4653, 4655, 4669, 4670, 4706, 4707, 4850, 4851, 4908, 4909, 6171, 6172, 6433, 6434, 6554, 6555, 7452, 7606, 7645, 7647, 7699, 7700, 7710, 7711, 7719, 7720, 7904, 8019, 8840, 8841, 8856, 8857, 9496, 9497, 11145, 11146, 11167, 11168, 11412, 11413, 11546, 11547, 11560, 11581, 11654, 11655, 11667, 11668, 12011, 12012, 12566, 12567, 14147, 14148, 14817, 14939, 14940, 15004, 15059, 15061, 16031, 16032, 16143, 16144, 16336, 16337, 16362, 16364, 16377, 16379, 16841, 16842, 16869, 17024, 17027, 17131, 17132, 17136, 17153, 17154, 17288, 17289, 17387, 17388, 17390, 17422, 17423, 17429, 17546, 17547, 17912, 17913, 19619, 19620, 19690, 19691, 19814, 19816, 19818, 19862, 19863, 20073, 20075, 20264, 20265, 20267, 20794, 20795, 21658, 21659, 22269, 22270, 22979, 22980, 23050, 23051, 23053, 23412, 23413, 23475, 23476, 23993, 23994, 24004, 24005, 24122, 24124, 24281, 24282, 24333, 24380, 24381, 24382, 24406, 24407, 24443, 24444, 24450, 24451, 24453, 24499, 24500, 24588, 24590, 24598, 24599, 24630, 24631, 24649, 24650, 25626, 25627, 25839, 25840, 25897, 25898, 26013, 26026, 26027, 26029, 26154, 26156, 26603, 26604, 26832, 26833, 27136, 27448, 27512, 27655, 27656, 27721, 27722, 28568, 28569, 28931, 1000050, 1000125, 1000127, 1000250) group by app_chaine_id) m) = '1212c9d95f60294c94597da5c02fea35' as membres_comme_le_rejeu,
       (select md5(coalesce(string_agg(concat_ws('|', app_chaine_id, cote, rang, hektor_user_id, nom_au_moment, pourcentage, origine, ecrit_par), ';' order by app_chaine_id, cote, rang), '')) from public.app_affaire_repartition) as empreinte_apres;
